export interface BuildingConfigData {
    id: string;
    name: string;
    cost: number;
    incomePerSecond: number;
    incomeCap: number;
    onClick: 'collect' | 'start_battle';
    tags: string[];                    // B 模块用，先留着
    maxLevel: number;

    /** 升到 level 级所需金币。level 从 1 开始 */
    upgradeCost: (level: number) => number;
    /** level 级的产出倍率 */
    incomeMultiplier: (level: number) => number;
    /** level 级的容量倍率 */
    capMultiplier: (level: number) => number;
}

export const BUILDING_CONFIG: Record<string, BuildingConfigData> = {
    stall: {
        id: 'stall',
        name: '小摊',
        cost: 100,
        incomePerSecond: 1,
        incomeCap: 50,
        onClick: 'collect',
        tags: ['餐饮', '低价'],
        maxLevel: 10,
        upgradeCost: (lv) => Math.floor(100 * Math.pow(1.8, lv - 1)),
        incomeMultiplier: (lv) => 1 + (lv - 1) * 0.5,   // 1级 1x，2级 1.5x，3级 2x
        capMultiplier: (lv) => 1 + (lv - 1) * 0.6,
    },
    portal: {
        id: 'portal',
        name: '关卡入口',
        cost: 300,
        incomePerSecond: 0,
        incomeCap: 0,
        onClick: 'start_battle',
        tags: ['特殊'],
        maxLevel: 1,
        upgradeCost: () => Infinity,
        incomeMultiplier: () => 1,
        capMultiplier: () => 1,
    },
};